# function to convert a UTC timestamp to local time based on timezone_offset (in minutes)
def utc_to_local(utc_timestamp: str, tz: int) -> str:
    utc_dt = dt.datetime.strptime(utc_timestamp, "%Y-%m-%d %H:%M:%S %z")
    local_dt = utc_dt - dt.timedelta(minutes=tz)
    return local_dt.strftime("%Y-%m-%d %H:%M:%S %Z")

